  Cv = `Esikatselussa oleva RSS-syöte ei vastaa nykyisiä asetuksia. Syöte on päivitettävä siihen syötteen URL-osoitteeseen, jota käytetään esikatselussa, jotta voimme luoda uuden tapahtuman. RSS-syötteen automatisointi otetaan oletusarvoisesti pois käytöstä. Sen voi muuttaa myöhemmin.`,
