  fS = `Käytä pelaajille mielenkiintoista ja merkityksellistä nimeä. Jos kyseessä on todella yksi vuoden tärkeimmistä päivityksistä, nimen tulisi kuvastaa tätä. Vältä yleisluontoisia nimiä, kuten <1>päivitys versioon 330.4</1>. Tuo sen sijaan esille, miksi päivitys on niin merkittävä.`,
