  wH = `Vuoden VR-peli ei yritä matkia todellisuutta vaan parantaa sitä! Se ottaa kaiken irti virtuaalitodellisuuden mahdollisuuksista ja rikkoo sen rajoja.`,
  TH = `Tämä peli on ollut kuvioissa jo jonkin aikaa. Se ei ole enää uusi tulokas, mutta kehittäjät ruokkivat luomustaan rakkaudella ja tuovat siihen edelleenkin uutta sisältöä.`,
