  UH = `Paras peli tien päällä`,
  WH = `Olivatko pelin mekaniikat mukaansatempaavia? Tekikö tarina vaikutuksen? Olivatko hahmojen ja ulkoasun suunnittelu omaa luokkaansa? Jäitkö koukkuun moninpeliin? Olipa syy mikä tahansa, tämän vuoden paras peli on klassikko jo syntyessään.`,
  GH = `Vuoden paras VR-peli ei tyydy jäljittelemään todellisuutta, vaan parantaa sitä huomattavasti. VR-laseista otetaan kaikki irti ja virtuaalista rimaa nostetaan entisestään.`,
  KH = `Tämä peli on ollut kuvioissa jo jonkin aikaa. Se ei ole enää uusi tulokas, mutta kehittäjät ruokkivat luomustaan rakkaudella ja tuovat siihen vuosien jälkeenkin uutta sisältöä.`,
  qH = `Joitain pelejä on kivempi pelata kimpassa kuin yksin. Saatat tarvita kaverin turvaamaan selustasi tai toverin, jota sinä voit puukottaa selkään. Riemulla ei ole rajoja, kun kaverit kokoontuvat pelaamaan tätä peliä.`,
  JH = `Visuaalisessa tyylissä ei ole kyse fotorealismin saavuttavista grafiikoista (vaikka se onkin jalo päämäärä sinänsä), vaan ainutlaatuisen ulkonäön ja ilmapiirin luomisesta peliin.`,
  YH = `Tämän pelin suunnittelijat ovat kokeellisten pelikokemusten kärjessä ja rikkovat rajoja ennennäkemättömän jännittävillä ja tajunnanräjäyttävillä yllätyksillään. Peli ihastutti, innoitti ja viihdytti uutuudellaan.`,
  XH = `Peli ei sovi arkajaloille, vaan vaatii sitkeyttä. Rankka mutta rakas peli.`,
  ZH = `Tämä peli ansaitsee tunnustuksen erinomaisesta musiikistaan. Sen alkuperäinen ääniraita on rautaa! `,
  QH = `Joinain päivinä vain tuhti tarinapohjainen peli maistuu, ja tämä peli antaa makeaa mahan täydeltä. Yhtä mukaansatempaava kuin saippuaooppera ja yhtä taidokkaasti punottu kuin maineikkaan TV-sarjan käsikirjoitus. Hatunnosto teille, pelintekijät. Herätitte meissä tunteita!`,
  $H = `Tämä peli on vastalääke kiireiselle päivälle. Se on rauhallinen, rentouttava ja vie huolet mennessään. Päivän zen-hetki.`,
  eU = `Peli oli niin hyvä, että halusit ottaa sen mukaan joka paikkaan. Ja niin teitkin! Peli vei mukanaan jo kotonakin, mutta tien päällä sitä oli vielä mahtavampi pelata.`,
  tU = `Vain VR`,
  nU = `VR-tuettu`,
  rU = `%1$s jäljellä seuraavaan arvontaan!`,
  iU = `Aikaa jäljellä ennen seuraavaa arvontaa.`,
