  tme = `Suuret ailahtelut kaaviossa (esim. välillä %1$s–%2$s FPS) voivat johtua VSync-ominaisuudesta, joka synkronoi kuvakehysten saapumisen näytön virkistystaajuuden kanssa repeämien välttämiseksi. Tämä voi johtaa %1$s FPS:n ja %2$s FPS:n näyterykelmiin, vaikka pelin keskimääräinen kuvataajuus olisi niiden välillä. Tämä on odotettua toimintaa VSynciltä, ja vaikka se voi vaikuttaa kuvan tahdistamiseen, se ei välttämättä aiheuta huomattavaa nykimistä.`,
